for name,items in [('Technical_Note',N),('Supplementary_Information',S)]:
 (R/'source'/(name+'.json')).write_text(json.dumps(items,indent=2,ensure_ascii=False)+'\n')
 lines=[]
 for e in items:
  k=e['type']
  if k=='title':lines+=['# '+e['text'],'']
  elif k=='heading':lines+=['#'*(e['level']+1)+' '+e['text'],'']
  elif k=='paragraph':lines+=[e['text'],'']
  elif k=='code':lines+=['```text',e['text'],'```','']
  elif k=='figure':lines+=['![Figure](../figures/'+e['file']+')',e['caption'],'']
  elif k=='table':
   t=T[e['id']];lines+=[t['caption'],'','| '+' | '.join(t['headers']).replace('\n',' ')+' |','| '+' | '.join(['---']*len(t['headers']))+' |']
   for row in t['rows']:lines+=['| '+' | '.join(str(v).replace('\n',' ') for v in row)+' |']
   lines+=[t['footnote'],'']
 (R/'source'/(name+'.md')).write_text('\n'.join(lines))
